import re


def _template(value, vars):
    def replace(match):
        key = match.group(1)
        return str(vars.get(key, os.environ.get(key, "")))
    return re.sub(r"{{\s*\.([A-Za-z_][\w]*)\s*}}", replace, str(value))


def _commands(task):
    if isinstance(task, str):
        return [task]
    if isinstance(task, list):
        return task
    task = task or {}
    cmds = task.get("cmds", []) or []
    if not cmds and task.get("cmd"):
        cmds = [task["cmd"]]
    return cmds


