    """Print the reference-style summary for one normalized task."""
    tasks = config.get("tasks") or {}
    task = tasks.get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    obj = task if isinstance(task, dict) else {}
    vars = dict(config.get("vars") or {})
    print(f"task: {name}")
    print()
    desc = obj.get("summary") or obj.get("desc", "")
    if desc:
        print(_template(desc, vars))
    print()
    if vars:
        print("vars:")
        for key, value in vars.items():
            # Task's summary uses YAML-compatible quoted strings for scalars.
            if isinstance(value, str):
                val = '"' + value.replace('\\', '\\\\').replace('"', '\\"') + '"'
            elif value is None:
                val = "null"
            elif isinstance(value, bool):
                val = str(value).lower()
            else:
                val = str(value)
            print(f"  {key}: {val}")
        print()
    cmds = _commands(task)
    rendered = []
    for command in cmds:
        if isinstance(command, dict):
            command = command.get("cmd", "")
        if command:
            rendered.append(_template(command, vars))
    if rendered:
        print("commands:")
        for command in rendered:
            print(f" - {command}")
    return 0


def check_status(config, name, cwd=None):
    """Return success only when status commands all report the task current."""
    task = (config.get("tasks") or {}).get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    task = task if isinstance(task, dict) else {}
    checks = task.get("status") or []
    if isinstance(checks, str):
