        if val is None: return ""
        if isinstance(val, bool): return str(val).lower()
        if isinstance(val, (list,dict)): return str(val)
        return str(val)
    return re.sub(r"{{\s*(.*?)\s*}}", sub, s)


def resolve_vars(variables, inherited=None, env=None):
    """Resolve simple static/ref Taskfile vars in declaration order."""
    result = dict(inherited or {})
    result.update(env or {})
    for key, raw in (variables or {}).items():
        if isinstance(raw, dict) and "ref" in raw:
