    'disable-fuzzy': 'TASK_DISABLE_FUZZY', 'failfast': 'TASK_FAILFAST',
    'dry': 'TASK_DRY', 'assume-yes': 'TASK_ASSUME_YES',
    'interactive': 'TASK_INTERACTIVE',
}


def _scalar(value):
    value = value.split(' #', 1)[0].strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        value = value[1:-1]
    low = value.lower()
    if low == 'true': return True
    if low == 'false': return False
    if low in ('null', '~', ''): return None
    try: return int(value)
    except ValueError: return value


def _read_config(path):
    """Read the common flat option subset of Task's YAML config."""
    out = {}
    try: lines = Path(path).read_text(encoding='utf-8').splitlines()
    except OSError: return out
    for line in lines:
        if not line.strip() or line.lstrip().startswith('#') or line[0].isspace():
            continue
        if ':' not in line: continue
        key, value = line.split(':', 1)
        out[key.strip().replace('_', '-')] = _scalar(value)
    return out


def load_config(cwd=None, environ=None):
    """Return merged .taskrc options, then overridden by TASK_* values.

    Current/parent directories have increasing priority, followed by HOME and
    XDG config as documented by Task.
    """
    cwd = Path(cwd or os.getcwd()).resolve()
    env = os.environ if environ is None else environ
    result = {}
    xdg = Path(env.get('XDG_CONFIG_HOME', str(Path(env.get('HOME', str(Path.home()))) / '.config'))) / 'task'
    for base in (xdg, Path(env.get('HOME', str(Path.home())))):
        for name in ('taskrc.yml', 'taskrc.yaml', '.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(base / name))
    for directory in reversed((cwd, *cwd.parents)):
        for name in ('.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(directory / name))
    for key, envkey in BOOLS.items():
        if envkey in env:
            val = env[envkey].lower()
            result[key] = val in ('true', '1', 'yes', 'on')
    if 'TASK_CONCURRENCY' in env:
        try: result['concurrency'] = int(env['TASK_CONCURRENCY'])
        except ValueError: pass
    return result

