        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    obj = task if isinstance(task, dict) else {}
    vars = dict(config.get("vars") or {})
    vars.update(obj.get("vars") or {})
    taskfile_path = os.path.abspath(taskfile) if taskfile and taskfile != "stdin" else "stdin"
    template_vars = dict(vars)
    template_vars.update({
        "TASK": name,
        "ROOT_DIR": os.path.abspath(cwd or os.path.dirname(taskfile_path)),
        "TASKFILE": taskfile_path,
        "ROOT_TASKFILE": taskfile_path,
        "TASKFILE_DIR": os.path.dirname(taskfile_path),
    })
    print(f"task: {name}")
    print()
    desc = obj.get("summary") or obj.get("desc", "")
    print(_template(desc, template_vars) if desc else "(task does not have description or summary)")
    print()
    if vars:
        print("vars:")
        for key, value in vars.items():
            # Task's summary uses YAML-compatible quoted strings for scalars.
            val = '"' + _summary_value(value).replace('\\', '\\\\').replace('"', '\\"') + '"'
            print(f"  {key}: {val}")
        print()
    deps = obj.get("deps") or []
    if isinstance(deps, str):
        deps = [deps]
